async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
  if (!store?.save) return;

  try {
    await store.save(session);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
  }
}

// Non-Error rejections stay typed as Error for hooks while keeping the raw rejection on cause.
function toError(error: unknown): Error {
  if (error instanceof Error) return error;
  return new Error(formatRejection(error), {cause: error});
}

function formatRejection(error: unknown): string {
  if (typeof error === 'string') return error;
  if (typeof error === 'object' && error !== null) return serialiseObject(error);
  return String(error);
}

function serialiseObject(rejected: object): string {
  try {
    return JSON.stringify(rejected) ?? '[unserialisable object]';
  } catch {
    return '[unserialisable object]';
  }
}

